% 
% % Set up a vector of the number of intervals to use
% n = 10.^(1:8);
% % Define a decreasing column vector of values for h
% h = double((b-a)./n)';
% 
% FEst = nan(size(h));
% for k = 1:length(n)
%     [~,yOut] = eulerMethod(f,[a Fexact(a)],n(k),h(k));
%     FEst(k) = yOut(end);
% end
% FErr = double(Fexact(b)*ones(size(FEst))-FEst);
% 
% ratio = [nan; FErr(2:end)./FErr(1:end-1)];
% estOrd = -log10(ratio);
% vals = [h FErr ratio estOrd];
% format long
% T = array2table(vals,"VariableNames",...
%     ["h", "Error", "Ratio", "Estimated Order"]);
% T(2:end,:)
%%
%[text] %[text:anchor:H_4654D1C6] ### Example: 3-point Gaussian quadrature
%[text] Consider how to calculate $\\displaystyle \\int\_{-1}^1 f(x)\\; dx${"altText":"int\_{-1}^1 f(x) dx"} using the best approximation with various numbers of points. A first-order approximation to $f(x)${"altText":"f(x)"} is linear, so then the integral is a trapezoid with area: 
%[text]{"align":"center"} %[text:anchor:H_7143CBF2] $\\frac{1}{2}\\left(f(-1)+f(1)\\right)2 = f(-1)+f(1) = m(-1)+f(0)+m(1)+f(0) = 2f(0)${"altText":"(1)\/(2)(f(-1)+f(1))2 = f(-1)+f(1) = m(-1)+f(0)+m(1)+f(0) = 2f(0)"}
%[text] %[text:anchor:H_D552B71E] The general form of an n-point Gaussian quadrature formula is
%[text]{"align":"center"} $\\displaystyle \\int\_{-1}^1 f(x)\\; dx \\approx \\sum\_{i=1}^n w\_if(x\_i)${"altText":"int\_{-1}^1 f(x) dx approximately sum\_{i=1}^n w\_if(x\_i)"},
%[text] where the weights, $w\_i${"altText":"w\_i"}, and the points, $x\_i${"altText":"x\_i"}, are chosen to minimize error. The one-point formula becomes 
%[text]{"align":"center"} $\\displaystyle \\int\_{-1}^1 f(x)\\; dx \\approx 2f(0)${"altText":"int\_{-1}^1 f(x) dx approximately 2f(0)"}    with $w\_1 = 2${"altText":"w\_1 = 2"} and $x\_1 = 0${"altText":"x\_1 = 0"}. 
%[text] The 3-point Gaussian quadrature formula is
%[text]{"align":"center"} $\\int\_{-1}^1 f(x)\\; dx \\approx \\frac{5}{9}f\\left(-\\sqrt{\\frac{3}{5}}\\right) + \\frac{8}{9}f(0)+\\frac{5}{9}f\\left(\\sqrt{\\frac{3}{5}}\\right)${"altText":"int\_{-1}^1 f(x) dx approximately (5)\/(9)f(-sqrt((3)\/(5))) + (8)\/(9)f(0)+(5)\/(9)f(sqrt((3)\/(5)))"}
%[text] Implementing this, we have
%[text] ```matlabCodeExample
%[text] function F = gauss3pt(f,a,b)
%[text] % gauss3pt implements a three-point Gaussian quadrature approximation 
%[text] % of the integral from a to b of f
%[text] 
%[text] % Set up the parameters
%[text] x1 = -sqrt(3/5);
%[text] x2 = 0;
%[text] x3 = sqrt(3/5);
%[text] w1 = 5/9;
%[text] w2 = 8/9;
%[text] w3 = 5/9;
%[text] 
%[text] % Change coordinates from [-1,1] to [a,b]
%[text] xShifted = (b-a)/2*[x1; x2; x3]+(b+a)/2;
%[text] wScaled = (b-a)/2*[w1 w2 w3];
%[text] 
%[text] % Use matrix multiplication to compute the weighted sum
%[text] F = wScaled*f(xShifted);
%[text] end
%[text] ```
f = @(x) 2*x.^5-3*x.^2;
a = -1.4;
b = 2.3;
Fexact = double(int(f(x),a,b))
Fapprox = Gauss3pt(f,a,b)
Ferror = Fexact-Fapprox
%[text] %[text:anchor:H_37F40C32] #### ![](text:image:6b7f)Try different values
%[text] 1. Try different functions of various degrees such as $f(x) = -8x^4+2x^3-5x${"altText":"f(x) = -8x^4+2x^3-5x"} or $f(x) = 1.7x^5-3${"altText":"f(x) = 1.7x^5-3"} or $f(x) = 0.6x^7-8x^2${"altText":"f(x) = 0.6x^7-8x^2"}. What do you observe about the error of this method?
%[text] 2. Try different functions that are not polynomials such as $f(x) = \\sin(x/4)${"altText":"f(x) = sin(x\/4)"} or $f(x) = e^{x}${"altText":"f(x) = e^{x}"}. What do you observe about the error of this method?
%[text] 3. Try different values for $a${"altText":"a"} and $b${"altText":"b"}, the endpoints of the integral. What do you observe about the error of this method?  \
%%
%[text] %[text:anchor:H_77284DB3] ![](text:image:5f48)**Exercise 2: Implement 2-point Gaussian quadrature**
%[text] The weights for a 2-point Gaussian quadrature approximation are $w\_1 = w\_2 = 1${"altText":"w\_1 = w\_2 = 1"} while the points to evaluate at are $x\_1 = -\\frac{1}{\\sqrt{3}}${"altText":"x\_1 = -(1)\/(sqrt(3))"} and $x\_2 = \\frac{1}{\\sqrt{3}}${"altText":"x\_2 = (1)\/(sqrt(3))"}. Use `gauss3pt` as a template for creating your function.
open("gauss2pt.m")
%%
%[text] %[text:anchor:H_093F1EC8] **Check Exercise 2: Implementing 2 point Gaussian quadrature**
% Run this code to test your gauss2pt function
calcError = TestGauss2PtCode(@gauss2pt)
